-- Backfill additional legacy checklists assigned to Junior.
-- Rebuilds the stable model/activity/assignment IDs generated by routine.js.
alter table public.app_records disable trigger app_records_guard_routine_write;

with groups(group_key, suffix, source_ck, checklist_ids) as (
  values
    ('repositor', 'tu5u6m', 'cjna9j02', array['cjna9j02']::text[]),
    ('gerente', '13a3kjo', 'ctyl5r5d', array['ctyl5r5d','cukl46nw']::text[])
),
source_rows as (
  select
    g.group_key, g.suffix, g.checklist_ids,
    c.org_id, c.data->'value' as ck
  from groups g
  join public.app_records c
    on c.module='ck'
   and c.record_id=g.source_ck
   and c.deleted_at is null
  where c.data->'value'->>'p'='qfgpxp1'
),
models as (
  select
    s.org_id, s.suffix, s.checklist_ids, s.ck,
    'legacy-assigned-checklist-qfgpxp1-'||s.suffix as model_id,
    coalesce((
      select jsonb_agg(jsonb_build_object(
        'id','legacy-assigned-activity-'||s.suffix||
          case when jsonb_typeof(s.ck->'t')='array' and jsonb_array_length(s.ck->'t')>0
            then '|turn|'||(turns.turn_no-1)::text else '' end||
          '|item|'||(steps.item_no-1)::text,
        'title',steps.step,
        'description','Checklist atribuído no cadastro do funcionário.'||
          case when jsonb_typeof(s.ck->'t')='array' and jsonb_array_length(s.ck->'t')>0
            then ' · Turno: '||turns.turn else '' end,
        'steps','[]'::jsonb,
        'checklistSnapshot',jsonb_build_array(steps.step),
        'turns',case when jsonb_typeof(s.ck->'t')='array' and jsonb_array_length(s.ck->'t')>0
          then jsonb_build_array(turns.turn) else '[]'::jsonb end,
        'source',jsonb_build_object('type','legacy-assigned-checklist-item','checklistId',s.checklist_ids[1]),
        'functionId','',
        'photo','none',
        'mandatory',true,
        'recurrence',jsonb_build_object('type','daily'),
        'time','08:00',
        'updatedAt',floor(extract(epoch from clock_timestamp())*1000)::bigint
      ) order by turns.turn_no,steps.item_no)
      from (
        select step, row_number() over () as item_no
        from unnest(string_to_array(s.ck->>'i','|')) as raw(step)
        where btrim(step)<>'' and left(btrim(step),1)<>'#'
      ) steps
      cross join lateral (
        select turn, row_number() over () as turn_no
        from jsonb_array_elements_text(
          case when jsonb_typeof(s.ck->'t')='array' and jsonb_array_length(s.ck->'t')>0
            then s.ck->'t' else '[""]'::jsonb end
        ) as turns(turn)
      ) turns
    ),'[]'::jsonb) as activities,
    floor(extract(epoch from clock_timestamp())*1000)::bigint as now_ms
  from source_rows s
)
insert into public.app_records(org_id,module,record_id,kind,data)
select
  m.org_id,'routineModels',m.model_id,'r:cro',
  jsonb_build_object(
    'id',m.model_id,
    'name',m.ck->>'n',
    'description','Migrado automaticamente do checklist atribuído ao funcionário.',
    'legacyId',m.checklist_ids[1],
    'createdAt',m.now_ms,
    'updatedAt',m.now_ms,
    'activities',m.activities,
    'legacySignature',m.suffix,
    'legacyChecklistIds',to_jsonb(m.checklist_ids)
  )
from models m
where not exists (
  select 1 from public.app_records existing
  where existing.org_id=m.org_id and existing.module='routineModels'
    and existing.record_id=m.model_id and existing.deleted_at is null
);

with groups(suffix) as (values ('tu5u6m'),('13a3kjo')),
assignments as (
  select
    o.id as org_id,
    'legacy-assigned-checklist-assignment-qfgpxp1-'||g.suffix as assignment_id,
    'legacy-assigned-checklist-qfgpxp1-'||g.suffix as model_id,
    floor(extract(epoch from clock_timestamp())*1000)::bigint as now_ms
  from public.organizations o cross join groups g
  where o.name='Atacarejo Super Tudo'
)
insert into public.app_records(org_id,module,record_id,kind,data)
select
  a.org_id,'routineAssignments',a.assignment_id,'r:cro',
  jsonb_build_object(
    'id',a.assignment_id,
    'modelId',a.model_id,
    'executorId','qfgpxp1',
    'from',(now() at time zone 'America/Sao_Paulo')::date::text,
    'until',null,
    'active',true,
    'source','legacy-assigned-checklist',
    'createdAt',a.now_ms,
    'updatedAt',a.now_ms
  )
from assignments a
join public.app_records m on m.org_id=a.org_id and m.module='routineModels'
  and m.record_id=a.model_id and m.deleted_at is null
where not exists (
  select 1 from public.app_records existing
  where existing.org_id=a.org_id and existing.module='routineAssignments'
    and existing.record_id=a.assignment_id and existing.deleted_at is null
);

alter table public.app_records enable trigger app_records_guard_routine_write;
